// Pick a random topic from a static list if no topic was provided via webhook/input.
// Customize this list to your content niche (motivational, facts, tech tips, etc.)
const topics = [
  "5 Mind-Blowing Facts About the Universe",
  "3 Habits That Will Change Your Life Forever",
  "Why Your Brain Lies to You Every Day",
  "The Secret Behind Successful People's Mornings",
  "5 Things Albert Einstein Said That Will Blow Your Mind",
  "How to Learn Anything 10x Faster",
  "3 Psychology Tricks Used on You Every Day",
  "The Real Reason You Procrastinate",
  "5 Ancient Secrets That Still Work Today",
  "Why Reading 10 Pages a Day Changes Everything"
];

const inputTopic = $input.first()?.json?.topic;
const topic = inputTopic || topics[Math.floor(Math.random() * topics.length)];

return [{ json: { topic } }];

// Parse the LLM response
const raw = $input.first().json.choices[0].message.content;

let parsed;
try {
  // Try to extract JSON from the response (LLM may wrap it in markdown code blocks)
  const jsonMatch = raw.match(/```json\n([\s\S]*?)\n```/) || raw.match(/```\n([\s\S]*?)\n```/);
  const jsonStr = jsonMatch ? jsonMatch[1] : raw;
  parsed = JSON.parse(jsonStr);
} catch (e) {
  // Fallback: treat the entire text as the script with default values
  parsed = {
    script: raw,
    title: $('Topic Selector').first().json.topic,
    description: raw.substring(0, 200) + " #Shorts #AI #Facts",
    tags: ["Shorts", "AI", "Facts", "Motivation", "Learn"],
    scenes: [
      { text: raw, visual: "Dynamic text animation on dark background" }
    ]
  };
}

// Attach topic for reference
parsed.topic = $('Topic Selector').first().json.topic;
return [{ json: parsed }];

// Collect video file URLs from Pexels response
// We target portrait (9:16) HD videos.
const pexelsData = $input.first().json;
const scriptData = $('Parse Script & Scenes').first().json;

const videoUrls = [];
if (pexelsData.videos) {
  pexelsData.videos.forEach(v => {
    const file = v.video_files.find(f => f.quality === 'hd' && f.width < f.height) ||
                 v.video_files.find(f => f.width < f.height) ||
                 v.video_files[0];
    if (file) videoUrls.push(file.link);
  });
}

// If no portrait videos, fall back to landscape (ffmpeg will crop)
if (videoUrls.length === 0 && pexelsData.videos && pexelsData.videos[0]) {
  videoUrls.push(pexelsData.videos[0].video_files[0].link);
}

return [{ json: { ...scriptData, videoUrls } }];

// Merge script data, video URLs, and audio binary reference
const scriptData = $('Collect Visual Assets').first().json;
const audioData = $('Text-to-Speech (StreamElements)').first();

// Build the ffmpeg command to assemble the final vertical (9:16) video.
// This command:
// 1. Takes the first stock video (looped to match audio length) as background
// 2. Crops/scales to 1080x1920 (9:16 portrait)
// 3. Overlays the TTS audio
// 4. Burns in subtitle text per scene
// The actual execution requires ffmpeg to be installed on the n8n host.

const videoUrl = scriptData.videoUrls[0] || '';
const outputPath = `/tmp/shorts_output_${Date.now()}.mp4`;
const audioPath = `/tmp/tts_audio_${Date.now()}.mp3`;

// ffmpeg command template (to be run in Execute Command node)
const ffmpegCmd = [
  `ffmpeg -y`,
  `-i "${videoUrl}"`,       // input: stock video (streamed via URL)
  `-i "${audioPath}"`,     // input: TTS audio file
  `-filter_complex "[0:v]scale=1080:1920:force_original_aspect_ratio=increase,crop=1080:1920,setsar=1[v]"`,
  `-map "[v]" -map 1:a`,
  `-shortest`,             // end when audio ends
  `-c:v libx264 -preset fast -crf 23`,
  `-c:a aac -b:a 128k`,
  `"${outputPath}"`
].join(' ');

return [{ json: {
  ...scriptData,
  audioPath,
  outputPath,
  ffmpegCmd
}}];

// Save audio binary to disk so ffmpeg can use it.
// n8n's binary data for the TTS audio is in the previous node.
// We write it to the audioPath computed earlier.
const { execSync } = require('child_process');
const fs = require('fs');

const prepData = $('Prepare FFmpeg Command').first().json;
const audioBuffer = $('Text-to-Speech (StreamElements)').first().binary?.data?.data;

if (audioBuffer) {
  fs.writeFileSync(prepData.audioPath, Buffer.from(audioBuffer, 'base64'));
}

return [{ json: prepData }];

// Check ffmpeg output and prepare YouTube upload metadata.
const ffmpegResult = $input.first().json;
const scriptData = $('Save Audio to Disk').first().json;

if (ffmpegResult.exitCode !== 0) {
  throw new Error(`FFmpeg failed: ${ffmpegResult.stderr}`);
}

return [{ json: {
  outputPath: scriptData.outputPath,
  title: scriptData.title,
  description: scriptData.description + '\n\n#Shorts #AI #AutomatedVideo',
  tags: scriptData.tags || [],
  topic: scriptData.topic
}}];

// Extract the upload URL from the Location header returned by YouTube.
// Then read the video file and upload it.
const { execSync } = require('child_process');
const fs = require('fs');

const initResponse = $input.first();
const uploadUrl = initResponse.json?.headers?.location ||
                  initResponse.json?.location;

const videoPath = $('Check FFmpeg Result').first().json.outputPath;

if (!uploadUrl) {
  throw new Error('YouTube resumable upload URL not found in response headers.');
}
if (!fs.existsSync(videoPath)) {
  throw new Error(`Video file not found at: ${videoPath}`);
}

const stats = fs.statSync(videoPath);
return [{ json: {
  uploadUrl,
  videoPath,
  fileSize: stats.size,
  title: $('Check FFmpeg Result').first().json.title
}}];

// Extract the uploaded video ID and build the YouTube Shorts URL.
const uploadResp = $input.first().json;
const videoId = uploadResp?.id || uploadResp?.snippet?.resourceId?.videoId;

if (!videoId) {
  // Upload may have returned the full video object
  const raw = JSON.stringify(uploadResp);
  console.log('YouTube upload response:', raw);
  throw new Error('Could not extract videoId from YouTube response.');
}

const youtubeUrl = `https://www.youtube.com/shorts/${videoId}`;
console.log(`Video published! URL: ${youtubeUrl}`);

return [{ json: {
  videoId,
  youtubeUrl,
  title: $('Check FFmpeg Result').first().json.title,
  success: true
}}];

